def find_first_duplicate(arr):
    # Create an empty dictionary to store numbers and their counts
    num_counts = {}

    # Iterate through the array and update the count for each number
    for num in arr:
        if num not in num_counts:
            num_counts[num] = 1
        else:
            num_counts[num] += 1

    # Find the first number with a count greater than 1
    for num in arr:
        if num_counts[num] > 1:
            return num

    # If no duplicates are found, return None
    return None

